<script>function cargarCostos(id){var u='<?php echo site_url("reporte_rentabilidad_viaje/costos");?>/'+id;$.getJSON(u,function(d){var h='<table class="table table-condensed"><tr><th>Fecha</th><th>Categoría</th><th>Concepto</th><th class="text-right">Monto</th><th></th></tr>';$.each(d,function(i,r){h+='<tr><td>'+r.egreso_fecha+'</td><td>'+r.egreso_categoria+'</td><td>'+(r.egreso_concepto||'')+'</td><td class="text-right">Bs '+parseFloat(r.egreso_monto).toFixed(2)+'</td><td><a onclick="return confirm(\'¿Desvincular este egreso del viaje? El egreso NO será eliminado.\')" href="<?php echo site_url("reporte_rentabilidad_viaje/desvincular_costo");?>/'+r.egreso_id+'" class="btn btn-xs btn-danger"><i class="fa fa-times"></i></a></td></tr>';});h+='</table>';$('#lista_costos').html(h);});}</script><?php endif;?>
